 * @param unboundAt       解绑时刻（UTC）
 * @param revokedConfirmations 同时撤销的一致性确认条数
 * @param deviceVersion   解绑后的装置版本（恢复空闲）
 */
public record TailUnbindResponse(
        long bindingId,
        long jobId,
        String deviceNo,
        Instant unboundAt,
        int revokedConfirmations,
